/* =====================================================================
   tools/lib/evals-bundle.js — pack evals/ for the page

   A page opened by double-click cannot read JSON files, so the eval set
   and a fingerprint of every golden answer (src/service/evals.js) are
   packed into evals/bundle.js, which index.html loads:

     MCX.evalBundle = { set: [...golden-set.json cases],
                        golden: [{ id, input, fp }] }   one per golden answer

   Written by tools/golden.js --update and checked by tools/validate.js.
   ===================================================================== */
'use strict';

const fs = require('fs');
const path = require('path');
const { MCX, root } = require('./load');

const DIR = path.join(root, 'evals');
const FILES = { set: path.join(DIR, 'golden-set.json'), answers: path.join(DIR, 'golden-answers.json'), bundle: path.join(DIR, 'bundle.js') };

function readJson(file, fallback) { return fs.existsSync(file) ? JSON.parse(fs.readFileSync(file, 'utf8')) : fallback; }
function readSet() { const s = readJson(FILES.set, { cases: [] }); return s.cases || []; }
function readAnswers() { return readJson(FILES.answers, []); }

/** The text of evals/bundle.js for an eval set and a list of golden answers [{ id, input, output }]. */
function bundleText(set, answers) {
  const golden = answers.map((c) => ({ id: c.id, input: c.input, fp: MCX.evals.fingerprint(c.output) }));
  return '/* Generated by tools/golden.js from evals/golden-set.json and evals/golden-answers.json. Do not edit. */\n' +
    '(function (global) {\n  var MCX = (global.MCX = global.MCX || {});\n  MCX.evalBundle = ' +
    JSON.stringify({ set: set, golden: golden }, null, 1) + ';\n})(typeof window !== \'undefined\' ? window : globalThis);\n';
}

function expectedBundle() { return bundleText(readSet(), readAnswers()); }
function writeBundle() { const text = expectedBundle(); fs.writeFileSync(FILES.bundle, text); return text; }

module.exports = { FILES, readSet, readAnswers, bundleText, expectedBundle, writeBundle };
